124	  rubric: string | object,
125	  llmOutput: string,
126	  grading?: GradingConfig,
127	  vars?: Record<string, VarValue>,
128	  assertion?: Assertion,
129	  options?: {
130	    throwOnError?: boolean;
131	    preferRemote?: boolean;
132	  },
133	  providerCallContext?: CallApiContextParams,
134	): Promise<GradingResult> {
135	  if (!grading) {
136	    throw new Error(
137	      'Cannot grade output without grading config. Specify --grader option or grading config.',
138	    );
139	  }
140	
141	  // Use remote grading when no provider is explicitly configured, or when a
142	  // caller injected an implicit default provider but still prefers remote.
143	  const shouldPreferRemote =
144	    options?.preferRemote ||
145	    (grading as LlmRubricGradingConfig).__promptfooPreferRemote ||
146	    !grading.provider;
147	  if (
148	    !grading.rubricPrompt &&
149	    shouldPreferRemote &&
150	    !cliState.config?.redteam?.provider &&
151	    cliState.config?.redteam &&
152	    shouldGenerateRemote({ canUseCodexDefaultProvider: true })
153	  ) {
154	    try {
155	      return {
156	        ...(await doRemoteGrading({
157	          task: 'llm-rubric',
