161	        })),
162	        assertion,
163	      };
164	    } catch (error) {
165	      return {
166	        ...fail(`Could not perform remote grading: ${error}`),
167	        assertion,
168	      };
169	    }
170	  }
171	
172	  try {
173	    return await runJsonGradingPrompt({
174	      assertion,
175	      checkName: 'llm-rubric check',
